import { DefineFunction, Schema } from "deno-slack-sdk/mod.ts";

/**
 * Custom function that saves a new member's masterdata and bank details,
 * posts a vCard contact card to the admin channel, and returns the SEPA
 * mandate details generated by the masterdata backend.
 *
 * Inputs and outputs mirror the legacy bot's `saveNewMember` step: all
 * values are text taken over unchanged from the signature webhook (Workflow
 * Builder webhook variables can only be text), so the existing workflow can
 * switch steps without remapping anything.
 */
export const SaveNewMemberFunction = DefineFunction({
  callback_id: "masterdata_save_new_member",
  title: "Neues Mitglied speichern",
  description:
    "Speichert ein neues Mitglied in den Stammdaten und der SEPA-Datei",
  source_file: "src/masterdata/functions/save_new_member/mod.ts",
  input_parameters: {
    properties: {
      joinedDate: { type: Schema.types.string, title: "Beitrittsdatum" },
      firstname: { type: Schema.types.string, title: "Vorname" },
      lastname: { type: Schema.types.string, title: "Nachname" },
      email: { type: Schema.types.string, title: "E-Mail" },
      phone: { type: Schema.types.string, title: "Telefonnummer" },
      birthday: { type: Schema.types.string, title: "Geburtstag" },
      street: { type: Schema.types.string, title: "Straße" },
      houseNumber: { type: Schema.types.string, title: "Hausnummer" },
      zip: { type: Schema.types.string, title: "Postleitzahl" },
      city: { type: Schema.types.string, title: "Wohnort" },
      sex: { type: Schema.types.string, title: "Geschlecht" },
      membershipType: {
        type: Schema.types.string,
        title: "Art der Mitgliedschaft",
      },
      IBAN: { type: Schema.types.string, title: "IBAN" },
      BIC: { type: Schema.types.string, title: "BIC" },
      accountOwner: { type: Schema.types.string, title: "Kontoinhaber" },
      signingDate: {
        type: Schema.types.string,
        title: "Datum der Unterschrift",
      },
      adminChannel: {
        type: Schema.slack.types.channel_id,
        title: "Admin Channel",
        description: "Channel, in den der Kontakt geschickt wird",
      },
    },
    required: [
      "joinedDate",
      "firstname",
      "lastname",
      "email",
      "phone",
      "birthday",
      "street",
      "houseNumber",
      "zip",
      "city",
      "sex",
      "membershipType",
      "IBAN",
      "BIC",
      "accountOwner",
      "signingDate",
      "adminChannel",
    ],
  },
  output_parameters: {
    properties: {
      mandateReference: { type: Schema.types.string, title: "Mandatsreferenz" },
      contactCardMessageLink: {
        type: Schema.types.string,
        title: "Link zur Kontaktnachricht",
      },
      initialAmount: {
        type: Schema.types.string,
        title: "Erstmaliger Einzugsbetrag",
        description: "Exkl. Aufnahmegebühr",
      },
      recurringAmount: {
        type: Schema.types.string,
        title: "Wiederkehrender Betrag",
        description: "Halbjährlich",
      },
    },
    required: [
      "mandateReference",
      "contactCardMessageLink",
      "initialAmount",
      "recurringAmount",
    ],
  },
});
